export const COUNTRY_BY_CC = new Map(WORLD_COUNTRIES.map((c) => [c.cc, c]));

export function findCountry(cc) {
  if (!cc) return null;
  return COUNTRY_BY_CC.get(String(cc).toUpperCase()) || null;
}
